  "identity": {
    "name": "Lumi & Bloom",
    "tagline": "Skin that feels like you.",
    "one_line_description": "Lumi & Bloom is a friendly, feel-good body care brand offering clean, nourishing skincare products designed for everyday rituals that make people glow from the outside in.",
