    {
      "slug": "brand",
      "title": "Our Brand",
      "role": "editorial",
      "goal": "Tell the brand origin story, communicate core values, and build an emotional connection with visitors who care about who they buy from \u2014 not just what they buy.",
      "meta_description": "Meet Lumi & Bloom \u2014 the clean body care brand built on the belief that your daily ritual should feel joyful, honest, and good for the planet.",
      "sections": [
        {
          "id": "brand-section-1",
          "type": "page_header",
          "intent": "Set the editorial tone for the brand story and signal to visitors that this page is a deeper, more personal experience.",
          "eyebrow": "Our Story",
          "headline": "Born from a Belief That Skincare Should Feel Good \u2014 Inside and Out",
          "subheadline": "We started Lumi & Bloom because we were tired of choosing between products that worked and products we could feel good about.",
          "body": null,
          "items": [],
          "ctas": [],
          "asset_ideas": [
            {
              "id": "brand-section-1-asset-1",
              "kind": "illustration",
              "subject": "A simple line-art illustration of two hands cupping a blooming flower, conveying care, nurturing, and the human element of the brand.",
              "purpose": "Editorial hero visual that humanizes the brand story section and sets a warm, personal tone.",
              "quantity": 1,
              "used_by": [
                "brand-section-1"
              ]
            }
          ]
        },
        {
          "id": "brand-section-2",
          "type": "story_block",
          "intent": "Walk visitors through the founding narrative in a personal, editorial voice that builds authenticity and emotional resonance.",
          "eyebrow": "How It Started",
          "headline": "A Kitchen Table, a Problem, and a Promise",
          "subheadline": null,
          "body": "Lumi & Bloom was founded in 2019 by two friends who couldn't find a body care brand that checked every box: genuinely clean formulas, ingredients they could pronounce, sustainable packaging, and a price point that didn't feel like a luxury tax. So they made their own. Starting with a small batch of whipped shea butter in a shared apartment kitchen, they spent two years testing, refining, and listening to their community. Today, Lumi & Bloom ships to customers across the country \u2014 but the founding promise hasn't changed: every product should make you feel taken care of, inside and out.",
          "items": [],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "brand-section-3",
          "type": "feature_grid",
          "intent": "Articulate the core brand values in a scannable, visually friendly format that resonates with the app-like layout aesthetic.",
          "eyebrow": "What We Stand For",
          "headline": "Our Values Aren't a Marketing Slide \u2014 They're Our Ingredient List",
          "subheadline": "Every decision we make \u2014 from formula to packaging to partnerships \u2014 runs through these four commitments.",
          "body": null,
          "items": [
            {
              "title": "Radically Transparent",
              "description": "Full ingredient lists, sourcing notes, and formulation rationale published for every product. No fine print, no mystery.",
              "metadata": {
                "icon": "magnifying-glass"
              }
            },
            {
              "title": "Genuinely Clean",
              "description": "No parabens, sulfates, synthetic dyes, or fragrance shortcuts. Every ingredient earns its place in the formula.",
              "metadata": {
                "icon": "leaf"
              }
            },
            {
              "title": "Sustainably Packaged",
              "description": "Recycled and recyclable materials across our full range. We're on a path to 100% plastic-free by 2026.",
              "metadata": {
                "icon": "recycle"
              }
            },
            {
              "title": "Community First",
              "description": "We co-develop products with our customer community. Your skin feedback shapes our next launch.",
              "metadata": {
                "icon": "people"
              }
            }
          ],
          "ctas": [
            {
              "label": "See Our Sustainability Commitments",
              "target_page": "sustainability"
            }
          ],
          "asset_ideas": []
        },
        {
