      "role": "editorial",
      "goal": "Demonstrate that Lumi & Bloom's environmental and ethical commitments are specific, measurable, and sincere \u2014 converting skeptical consumers into loyal advocates.",
      "meta_description": "Lumi & Bloom's sustainability commitments: clean ingredients, recycled packaging, carbon offsetting, and a plastic-free pledge by 2026.",
      "sections": [
        {
          "id": "sustainability-section-1",
          "type": "page_header",
          "intent": "Open the sustainability story with a bold, honest statement that signals this page is about real commitments \u2014 not greenwashing.",
          "eyebrow": "Our Planet Pledge",
          "headline": "Good for Your Skin. Better for the Planet.",
          "subheadline": "We believe beauty shouldn't cost the earth. Here's exactly what we're doing about it \u2014 and where we still have work to do.",
          "body": null,
          "items": [],
          "ctas": [],
          "asset_ideas": [
            {
              "id": "sustainability-section-1-asset-1",
              "kind": "illustration",
              "subject": "A minimal SVG illustration of a globe wrapped gently in a leafy botanical vine, suggesting care for the natural world.",
